import json, random, subprocess, sys
from fractions import Fraction

NEW = "/home/c/brix2/b/task021/relay.py"
NET = "/tmp/md/net2.json"

def run(args):
    p = subprocess.run([sys.executable, NEW] + args, capture_output=True)
    return p.returncode, p.stdout, p.stderr

def peak(num, den):
    if den == 0:
        return "0.000000"
    q = (2 * num * 10**6 + den) // (2 * den)
    return "%d.%06d" % (q // 10**6, q % 10**6)

def reference(links, a, b, events, items):
    # Independent ground-truth simulation.
    nup = {}
    lup = {(l["from"], l["to"]): l["up"] for l in links}
    dn, dl = set(), set()
    periods = []
    cur = None
    for ev in events:
        t, kind = ev[0], ev[1]
        if kind == 0:
            node, up = ev[2], ev[3]
            if nup.get(node, True) == up:
                pass
            else:
                nup[node] = up
                if up:
                    dn.discard(node)
                else:
                    if cur is None:
                        cur = [t, None, set(), set()]
                        periods.append(cur)
                    dn.add(node); cur[2].add(node)
        else:
            pair = (ev[2], ev[3]); up = ev[4]
            if lup[pair] == up:
                pass
            else:
                lup[pair] = up
                if up:
                    dl.discard(pair)
                else:
                    if cur is None:
                        cur = [t, None, set(), set()]
                        periods.append(cur)
                    dl.add(pair); cur[3].add(pair)
        if cur is not None and not dn and not dl:
            cur[1] = t
            cur = None
    out = []
    for s, e, en, el in periods:
        buck = [[], [], []]
        for it in items:
            t = it[2]
            if not (a <= t <= b):
                continue
            if t < s:
                ph = 0
            elif e is None or t < e:
                ph = 1
            else:
                ph = 2
            buck[ph].append(it)
        stats = []
        for recs in buck:
            D = sum(1 for r in recs if r[3] == 0)
            X = len(recs) - D
            N = len(recs)
            ds = sorted(r[4] for r in recs if r[3] == 0)
            p95 = ds[(95 * D + 99) // 100 - 1] if D else None
            stats.append([N, D, X, peak(D, N), peak(X, N), p95])
        lk = [[l["from"], l["to"]] for l in links
              if l["up"] and ((l["from"], l["to"]) in el
                              or l["from"] in en or l["to"] in en)]
        out.append([s, e, (e - s) if e is not None else None, stats, lk])
    return {"a": a, "b": b, "periods": out}

def make_net():
    nodes = ["n%d" % i for i in range(random.randint(2, 5))]
    links, seen = [], set()
    for u in nodes:
        for v in nodes:
            if u != v and (u, v) not in seen and random.random() < 0.55:
                seen.add((u, v))
                links.append({"from": u, "to": v, "cost": 1,
                              "bandwidth": 1,
                              "latency": random.randint(0, 20),
                              "up": random.random() < 0.75})
    if not [l for l in links if l["up"]]:
        links.append({"from": nodes[0], "to": nodes[1], "cost": 1,
                      "bandwidth": 1, "latency": 1, "up": True})
    json.dump({"nodes": nodes, "links": links}, open(NET, "w"))
    return nodes, links

def make_events(nodes, links, a, b):
    up_links = [(l["from"], l["to"]) for l in links if l["up"]]
    t, ev = a, []
    for _ in range(random.randint(0, 14)):
        t = min(b, t + random.choice([0, 0, 0, 1, 1, 4]))
        r = random.random()
        if up_links and r < 0.55:
            u, v = random.choice(up_links)
            ev.append([t, 1, u, v, random.random() < 0.4])
        else:
            ev.append([t, 0, random.choice(nodes),
                       random.random() < 0.4])
    return ev

def make_data(nodes, links, a, b):
    pairs = [(l["from"], l["to"]) for l in links]
    t, data = a, []
    for i in range(random.randint(0, 15)):
        t = min(b, t + random.choice([0, 0, 1, 2, 5]))
        s = random.choice([0, 0, 1, 2])
        if s == 2:
            data.append(["p%d" % i, "f", t, 2, None, []])
        elif s == 0:
            data.append(["p%d" % i, "f", t, 0, random.randint(0, 500),
                         [nodes[0]]])
        else:
            u, v = random.choice(pairs)
            data.append(["p%d" % i, "f", t, 1, random.randint(0, 500),
                         [u, v]])
    return data

bad = 0
for trial in range(2000):
    nodes, links = make_net()
    a = random.randint(0, 8); b = a + random.randint(0, 40)
    ev = make_events(nodes, links, a, b)
    data = make_data(nodes, links, a, b)
    args = [NET, str(a), str(b), json.dumps(ev), json.dumps(data)]
    rc, out, err = run(["multidrill"] + args)
    assert rc == 0, (trial, rc, err, args)
    expected = reference(links, a, b,
                         [(e[0], e[1], *e[2:]) for e in ev],
                         [tuple(x) for x in data])
    got = json.loads(out.decode())
    # also enforce byte contract: compact separators, key order
    assert out == (json.dumps(expected, ensure_ascii=False,
                              separators=(",", ":")).encode() + b"\n"), \
        (trial, out, expected)
    if got != expected:
        bad += 1
        print("MISMATCH", trial)
        print(json.dumps(args))
        print("got ", got)
        print("want", expected)
        if bad > 2:
            break
print("reference fuzz: 2000 trials, %d mismatch" % bad)
sys.exit(1 if bad else 0)

